74	    pub fn all_dependencies(&self) -> impl Iterator<Item = AnyJsExpression> {
75	        self.dependencies_node
76	            .as_ref()
77	            .and_then(|x| Some(x.as_js_array_expression()?.elements().into_iter()))
78	            .into_iter()
79	            .flatten()
80	            .filter_map(|x| x.ok()?.as_any_js_expression().cloned())
81	    }
