fn is_react_component_or_hook(function: &AnyJsFunctionOrMethod) -> bool {
    match function {
        AnyJsFunctionOrMethod::AnyJsFunction(function) => function
            .binding()
            .and_then(|binding| {
                let token = binding.as_js_identifier_binding()?.name_token().ok()?;
                let name = token.text_trimmed();
                Some(is_react_component(name) || is_react_hook(name))
            })
            .unwrap_or(false),
        AnyJsFunctionOrMethod::JsMethodObjectMember(member) => member
            .name()
            .ok()
            .and_then(|name| name.name())
            .is_some_and(|name| {
                let name = name.text();
                is_react_component(name) || is_react_hook(name)
            }),
    }
}

