#[cfg(test)]
mod scratch_verify {
    use biome_analyze::{AnalysisFilter, ControlFlow, Never, RuleFilter};
    use biome_js_parser::{parse, JsParserOptions};
    use biome_js_syntax::JsFileSource;
    use biome_analyze::options::AnalyzerOptions;

    fn count(src: &str) -> usize {
        let parsed = parse(src, JsFileSource::jsx(), JsParserOptions::default());
        let filter = AnalysisFilter {
            enabled_rules: Some(&[RuleFilter::Rule("correctness", "useHookAtTopLevel")]),
            ..AnalysisFilter::default()
        };
        let options = AnalyzerOptions::default();
        let mut n = 0usize;
        crate::analyze(&parsed.tree(), filter, &options, JsFileSource::jsx(), |signal| {
            if signal.diagnostic().is_some() {
                n += 1;
            }
            ControlFlow::<Never>::Continue(())
        });
        n
    }

    #[test]
    fn verify_scenarios() {
        // 1. component (function decl) in test -> valid
        assert_eq!(count("test('x', () => { function Component() { useEffect(); } });"), 0, "fn decl component in test");
        // 2. component (arrow) in test -> valid
        assert_eq!(count("test('x', () => { const Component = () => { useEffect(); }; });"), 0, "arrow component in test");
        // 3. renderHook callback in test -> valid
        assert_eq!(count("test('x', () => { renderHook(() => useEffect()); });"), 0, "renderHook callback");
        // 4. named nested function within component in test -> flagged
        assert_eq!(count("test('x', () => { function Component() { function nested() { useEffect(); } } });"), 1, "named nested fn");
        // sanity: a.map arrow still flagged
        assert_eq!(count("function Component1({a}) { a.map(() => useEffect()); }"), 1, "a.map arrow");
        // sanity: top-level component valid
        assert_eq!(count("function Component1() { useEffect(); }"), 0, "top-level component");
    }
